const dbPromise=new Promise((resolve,reject)=>{if(remoteMode){resolve(null);return}const req=indexedDB.open('folio-pdfs',1);req.onupgradeneeded=()=>req.result.createObjectStore('pdfs');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});dbPromise.catch(()=>{});
async function pdfStore(action,id,value){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('pdfs',action==='get'?'readonly':'readwrite');const store=tx.objectStore('pdfs');const req=action==='get'?store.get(id):action==='delete'?store.delete(id):store.put(value,id);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error)})}
function existingTags(){const tags=new Map();for(const tag of [...(settings.collections||[]),...papers.flatMap(p=>p.tags||[])]){const value=tag.trim();if(value&&!tags.has(value.toLowerCase()))tags.set(value.toLowerCase(),value)}return [...tags.values()].sort((a,b)=>a.localeCompare(b))}
function parseTags(value){const known=new Map(existingTags().map(t=>[t.toLowerCase(),t]));const result=new Map();for(const part of value.split(',')){const tag=part.trim();if(tag&&!result.has(tag.toLowerCase()))result.set(tag.toLowerCase(),known.get(tag.toLowerCase())||tag)}return [...result.values()]}
function collectionSettings(){return `<section class="panel"><h2>Collections & tags</h2><p>Rename collections across your library or remove tags from papers.</p><button type="button" class="button" data-manage-collections>Manage collections</button></section>`}
async function changeCollection(oldName,newName){
 if(saving||uploading)throw new Error('Please wait for the current save or upload.');
 const same=t=>t.toLowerCase()===oldName.toLowerCase();
 if(!existingTags().some(same))throw new Error('This collection no longer exists.');
 let target=null;
 if(newName!==null){target=newName.trim();if(!target||target.length>200||target.includes(','))throw new Error('Enter a collection name of 1–200 characters without commas.');target=existingTags().find(t=>!same(t)&&t.toLowerCase()===target.toLowerCase())||target}
 const beforePapers=papers,beforeSettings=settings;
 const unique=tags=>[...new Map(tags.map(t=>[t.toLowerCase(),t])).values()];
 papers=papers.map(p=>{if(!(p.tags||[]).some(same))return p;return {...p,tags:unique(p.tags.flatMap(t=>same(t)?target===null?[]:[target]:[t])),updated:Date.now()}});
 settings={...settings,collections:unique((settings.collections||[]).flatMap(t=>same(t)?target===null?[]:[target]:[t]))};
 if(target&&!settings.collections.some(t=>t.toLowerCase()===target.toLowerCase()))settings.collections.push(target);
 try{if(remoteMode)await persistRemote();else{await save();await saveSettings()}}
 catch(err){if(!remoteMode){papers=beforePapers;settings=beforeSettings}throw err}
 if(collection&&same(collection)){collection=target||'';location.hash=collection?'collection='+encodeURIComponent(collection):view}
 return target;
}
function manageCollections(){
 const tags=existingTags();
 modal(modalTitle('Manage collections.')+`<p class="collection-help">Rename a tag everywhere it is used. Removing a tag keeps your papers and PDFs.</p><div id="collection-manager" class="collection-manager">${tags.length?tags.map(tag=>`<div class="collection-manager-row"><div><strong>${esc(tag)}</strong><small>${papers.filter(p=>(p.tags||[]).some(t=>t.toLowerCase()===tag.toLowerCase())).length} papers</small></div><div class="collection-row-actions"><button type="button" class="button" data-rename-tag="${esc(tag)}" aria-label="Rename ${esc(tag)}">Rename</button><button type="button" class="button danger" data-remove-tag="${esc(tag)}" aria-label="Remove ${esc(tag)}">Remove</button></div></div>`).join(''):'<p>No collections yet. Create one or add tags to a paper.</p>'}</div><div class="modal-actions"><button type="button" class="button" data-close>Done</button><button type="button" class="button primary" id="add-collection">${icon('plus')}New collection</button></div>`);
 $('#collection-manager').onclick=e=>{if(saving||uploading)return;const b=e.target.closest('button');if(!b)return;if(b.dataset.renameTag)renameCollection(b.dataset.renameTag);if(b.dataset.removeTag){const tag=b.dataset.removeTag;const count=papers.filter(p=>(p.tags||[]).some(t=>t.toLowerCase()===tag.toLowerCase())).length;confirmAction('Remove '+tag+'?',`Remove this tag from ${count} ${count===1?'paper':'papers'} and from your collections? Your papers, notes, and PDFs are kept.`,async()=>{await changeCollection(tag,null);toast('Collection removed.')})}};
}
function renameCollection(tag){
 modal(modalTitle('Rename collection.')+`<form id="rename-collection-form"><div class="field"><label for="rename-collection-name">Collection name</label><input id="rename-collection-name" value="${esc(tag)}" required maxlength="200"><small>Updates every paper using this tag. Choosing an existing collection name merges the two collections.</small></div><div id="rename-collection-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="button" id="back-to-collections">Back</button><button type="submit" class="button primary" id="save-collection-name">Save name</button></div></form>`);
 $('#back-to-collections').onclick=manageCollections;
 $('#rename-collection-form').onsubmit=async e=>{e.preventDefault();if(saving||uploading)return;const button=$('#save-collection-name');button.disabled=true;try{await changeCollection(tag,$('#rename-collection-name').value);render();manageCollections();toast('Collection updated.')}catch(err){$('#rename-collection-error').textContent=err.message}finally{button.disabled=false}};
}
function tagField(id,value=''){return `<div class="field tag-field"><label for="${id}">Collections / tags</label><input id="${id}" value="${esc(value)}" placeholder="Type to find a collection…" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}-suggestions" aria-describedby="${id}-help"><div id="${id}-suggestions" class="tag-suggestions" role="listbox" aria-label="Existing collections" hidden></div><small id="${id}-help">Choose an existing tag, or type a new one. Separate multiple tags with commas.</small></div>`}
function attachTagSuggestions(id){
 const input=$('#'+id),list=$('#'+id+'-suggestions');let matches=[],active=-1,dismissed=false;
 const token=()=>{const caret=input.selectionStart??input.value.length;const start=caret===0?0:input.value.lastIndexOf(',',caret-1)+1;const next=input.value.indexOf(',',caret);return {start,end:next<0?input.value.length:next}};
 const hide=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant')};
 const paint=()=>{list.innerHTML=matches.map((tag,i)=>`<button type="button" role="option" tabindex="-1" id="${id}-option-${i}" data-tag-index="${i}" aria-selected="${i===active}" class="${i===active?'active':''}">${esc(tag)}</button>`).join('');list.hidden=!matches.length;input.setAttribute('aria-expanded',String(!!matches.length));if(active>=0)input.setAttribute('aria-activedescendant',id+'-option-'+active);else input.removeAttribute('aria-activedescendant')};
 const update=()=>{if(dismissed)return;const {start,end}=token();const query=input.value.slice(start,end).trim().toLowerCase();const selected=new Set(parseTags(input.value.slice(0,start)+input.value.slice(end)).map(t=>t.toLowerCase()));matches=existingTags().filter(t=>!selected.has(t.toLowerCase())&&t.toLowerCase().includes(query)).sort((a,b)=>Number(b.toLowerCase().startsWith(query))-Number(a.toLowerCase().startsWith(query))||a.localeCompare(b));active=-1;paint()};
 const choose=index=>{const tag=matches[index];if(!tag)return;const {start,end}=token();const prefix=input.value.slice(0,start);const suffix=input.value.slice(end);const replacement=(prefix?' ':'')+tag+(suffix?'':', ');input.value=prefix+replacement+suffix;input.focus();input.setSelectionRange(prefix.length+replacement.length,prefix.length+replacement.length);hide();dismissed=true};
 input.oninput=()=>{dismissed=false;update()};input.onfocus=()=>{dismissed=false;update()};input.onclick=()=>{dismissed=false;update()};input.onblur=hide;
 input.onkeydown=e=>{if(e.isComposing)return;if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();dismissed=true;hide();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden){dismissed=false;update()}if(matches.length){active=(active+(e.key==='ArrowDown'?1:active<0?0:-1)+matches.length)%matches.length;paint();$('#'+id+'-option-'+active)?.scrollIntoView({block:'nearest'})}}else if(e.key==='Enter'&&!list.hidden&&matches.length){e.preventDefault();choose(active<0?0:active)}};
 list.onmousedown=e=>e.preventDefault();list.onclick=e=>{const button=e.target.closest('[data-tag-index]');if(button)choose(Number(button.dataset.tagIndex))};
}
let addMode='url',selectedFile=null,readerUrl='',lookedUpMetadata=null,metadataLookupSequence=0;
function addPaper(){selectedFile=null;addMode='url';renderAdd()}
function renderAdd(){lookedUpMetadata=null;metadataLookupSequence++;modal(modalTitle('Make room for a new idea.')+`<p style="font-size:12px">Add a paper from a link, a PDF, or your own citation details.</p><div class="tabs"><button data-add-tab="url" class="${addMode==='url'?'active':''}">Paper URL / DOI</button><button data-add-tab="pdf" class="${addMode==='pdf'?'active':''}">Upload PDF</button><button data-add-tab="manual" class="${addMode==='manual'?'active':''}">Manual entry</button></div><form id="add-form">${addMode==='url'?'<div class="field"><label for="paper-url">Paper URL or DOI</label><input id="paper-url" placeholder="https://eprint.iacr.org/2019/953 or 10.1137/0218012"><small>IACR ePrint, arXiv, publisher links, or a DOI. IACR ePrint, ACM Digital Library, Springer chapters, TCHES articles, and DOIs can fill citation details. Paste a link, then click Look up metadata.</small></div><button type="button" class="button" id="lookup">'+icon('search')+'Look up metadata</button>':addMode==='pdf'?`<label class="upload-zone" for="pdf-upload" style="display:block">${icon('upload')}<p id="file-label">Choose a PDF to add to your library</p><small>PDF files up to 50 MB · ${remoteMode?'Uploaded to your Google Drive':'Stored on this device'}</small></label><input id="pdf-upload" type="file" accept="application/pdf,.pdf" hidden>`:''}<div class="field"><label for="paper-title">Title *</label><input id="paper-title" required maxlength="500" placeholder="The title of the paper"></div><div class="field"><label for="paper-authors">Authors</label><input id="paper-authors" placeholder="Separate authors with semicolons"></div><div class="two-fields"><div class="field"><label for="paper-year">Publication year</label><input id="paper-year" type="number" min="1400" max="2100" placeholder="2026"></div><div class="field"><label for="paper-venue">Conference / journal</label><input id="paper-venue" placeholder="e.g. EUROCRYPT"></div></div>${tagField('paper-tags')}<div class="two-fields"><div class="field"><label for="paper-status">Reading status</label><select id="paper-status"><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></div><div class="field"><label for="paper-priority">Importance</label><select id="paper-priority"><option value="normal">Normal</option><option value="high">High</option><option value="low">Low</option></select></div></div><div id="add-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="button" data-close>Cancel</button><button class="button primary" id="save-paper" type="submit">${icon('plus')}Add to library</button></div></form>`);if(addMode==='pdf')$('#pdf-upload').onchange=e=>{selectedFile=e.target.files[0];if(selectedFile){$('#file-label').textContent=selectedFile.name;$('#paper-title').value=selectedFile.name.replace(/\.pdf$/i,'').replace(/[_-]/g,' ')}};attachTagSuggestions('paper-tags');$('#add-form').onsubmit=submitAdd;if($('#lookup'))$('#lookup').onclick=lookupMetadata;}
function paperInput(value){const clean=value.trim();return /^(?:link\.springer(?:nature)?\.com|dl\.acm\.org|tches\.iacr\.org|eprint\.iacr\.org|ia\.cr)\//i.test(clean)?'https://'+clean:clean}
function getDoi(value){let clean=paperInput(value).replace(/^doi:\s*/i,'');try{const u=new URL(clean);if(!/^https?:$/.test(u.protocol)||u.username||u.password||u.port)return '';if(/^(?:dx\.)?doi\.org$/i.test(u.hostname))clean=decodeURIComponent(u.pathname.slice(1));else if(['link.springer.com','link.springernature.com'].includes(u.hostname)&&u.pathname.startsWith('/chapter/'))clean=decodeURIComponent(u.pathname.slice('/chapter/'.length));else if(u.hostname==='dl.acm.org'){const match=u.pathname.match(/^\/doi\/(?:abs\/|full\/|pdf\/|epdf\/)?(10\.\d{4,9}\/.+?)\/?$/i);if(!match)return '';clean=decodeURIComponent(match[1])}else return ''}catch{if(/^https?:/i.test(clean))return ''}return /^10\.\d{4,9}\/\S+$/i.test(clean)?clean:''}
function getTchesArticleId(value){try{const u=new URL(paperInput(value));if(!/^https?:$/.test(u.protocol)||u.hostname!=='tches.iacr.org'||u.username||u.password||u.port)return '';return u.pathname.match(/^\/index\.php\/TCHES\/article\/(?:view|download)\/([1-9]\d{0,9})(?:\/[1-9]\d{0,9})?\/?$/i)?.[1]||''}catch{return ''}}
function getEprintId(value){try{const u=new URL(paperInput(value));if(!/^https?:$/.test(u.protocol)||!['eprint.iacr.org','ia.cr'].includes(u.hostname)||u.username||u.password||u.port)return '';return u.pathname.match(/^\/((?:19|20)\d{2}\/[1-9]\d{0,9})(?:\.pdf)?\/?$/)?.[1]||''}catch{return ''}}
async function lookupPaper(value){const doi=getDoi(value);if(doi)return crossrefPaper((await fetchJson('https://api.crossref.org/works/'+encodeURIComponent(doi))).message);const id=getTchesArticleId(value);if(id)return fetchJson('/api/tches?id='+encodeURIComponent(id));const eprintId=getEprintId(value);if(eprintId)return fetchJson('/api/eprint?id='+encodeURIComponent(eprintId));throw new Error('Use an IACR ePrint link, a DOI, an ACM Digital Library link, a Springer chapter link, or a TCHES article link. Other links can be saved with your own details.')}
async function fetchJson(url,options={}){const r=await fetch(url,{...options,signal:AbortSignal.timeout(20000)});if(!r.ok){const data=await r.json().catch(()=>({}));throw new Error(typeof data.error==='string'?data.error:`Service returned ${r.status}. Please try again.`)}return r.json()}
function crossrefVenue(w){const venue=w['container-title']?.[0]||w.event?.name||'';if(/\bACM\b/i.test(venue)&&/Conference on Computer and Communications Security/i.test(venue))return 'ACM CCS';if(/^IEEE Transactions on Information Forensics (?:and|&) Security$/i.test(venue.trim()))return 'IEEE TIFS';return venue}
function crossrefPaper(w){return {id:crypto.randomUUID(),title:w.title?.[0]||'Untitled paper',authors:(w.author||[]).map(a=>[a.given,a.family].filter(Boolean).join(' ')).filter(Boolean).join('; '),year:(w.published?.['date-parts']||w.issued?.['date-parts'])?.[0]?.[0]||'',venue:crossrefVenue(w),doi:w.DOI||'',url:w.URL||'',tags:[],status:'unread',importance:'normal',notes:'',added:Date.now(),updated:Date.now(),metadataSource:'Crossref',type:w.type}}
async function lookupMetadata(){const source=paperInput($('#paper-url').value);const sequence=++metadataLookupSequence;lookedUpMetadata=null;const b=$('#lookup');b.disabled=true;b.textContent='Looking up\u2026';try{const p=await lookupPaper(source);if(sequence!==metadataLookupSequence||source!==paperInput($('#paper-url')?.value||'')||addMode!=='url')return;$('#paper-title').value=p.title;$('#paper-authors').value=p.authors;$('#paper-year').value=p.year;$('#paper-venue').value=p.venue;lookedUpMetadata={...p,source};$('#add-error').textContent='';toast('Citation details found. Review before saving.')}catch(e){if(sequence===metadataLookupSequence)$('#add-error').textContent=e.message+' You can still enter details manually.'}finally{b.disabled=false;b.innerHTML=icon('search')+'Look up metadata'}}
async function submitAdd(e){e.preventDefault();if(saving||uploading)return;const error=$('#add-error');const b=$('#save-paper');b.disabled=true;try{const source=paperInput($('#paper-url')?.value||'');const metadata=lookedUpMetadata?.source===source?lookedUpMetadata:null;const doi=getDoi(source)||metadata?.doi||'';if($('#lookup')?.disabled)throw new Error('Wait for the citation lookup to finish.');if(source&&!doi&&!safeUrl(source))throw new Error('Enter a valid http or https paper URL.');if(addMode==='pdf'&&!selectedFile)throw new Error('Choose a PDF first.');if(selectedFile){if(selectedFile.size>50*1024*1024)throw new Error('Please choose a PDF smaller than 50 MB.');const bytes=await selectedFile.slice(0,5).text();if(bytes!=='%PDF-')throw new Error('This file does not appear to be a valid PDF.');}const eprintId=getEprintId(source);if(eprintId&&papers.some(p=>getEprintId(p.url||'')===eprintId))throw new Error('This ePrint paper is already in your library.');if(doi&&papers.some(p=>p.doi?.toLowerCase()===doi.toLowerCase()))throw new Error('This DOI is already in your library.');const p={id:crypto.randomUUID(),title:$('#paper-title').value.trim(),authors:$('#paper-authors').value.trim(),year:Number($('#paper-year').value)||'',venue:$('#paper-venue').value.trim(),tags:parseTags($('#paper-tags').value),status:$('#paper-status').value,importance:$('#paper-priority').value,url:safeUrl(source)||(doi?'https://doi.org/'+doi:''),doi,metadataSource:metadata?.metadataSource||'',type:metadata?.type||'',notes:'',added:Date.now(),updated:Date.now()};if(!p.title)throw new Error('Enter a paper title.');if(selectedFile){uploading=remoteMode;p.pdfName=selectedFile.name;if(remoteMode){if(!driveToken||Date.now()>=tokenExpiry)throw new Error('Connect Google Drive in Settings before uploading a PDF.');p.drivePdfId=await driveUpload(selectedFile,p.id+'.pdf',await driveFolder(true));}else{p.pdfId=p.id;await pdfStore('put',p.pdfId,selectedFile)}}papers.unshift(enrichVenue(p));await save();close();render();toast('Paper added. A new idea, collected.')}catch(err){error.textContent=err.message}finally{uploading=false;b.disabled=false}}
function details(id,external=false){const p=(external?recommendations:papers).find(p=>p.id===id);if(!p)return;modal(modalTitle(p.title)+`<p style="font-size:12px">${esc(p.authors)} · ${esc(p.year||'Year not recorded')}</p><div class="detail-links">${p.pdfId||p.drivePdfId?`<button class="button primary" data-read="${esc(p.id)}">${icon('book')}Read PDF</button>`:''}${safeUrl(p.url|| (p.doi?'https://doi.org/'+p.doi:''))?`<a class="button" href="${esc(safeUrl(p.url||'https://doi.org/'+p.doi))}" target="_blank" rel="noopener noreferrer">${icon('link')}Open paper ↗</a>`:''}${!external?`<button class="button" data-cite="${esc(p.id)}">${icon('download')}Cite</button>${remoteMode?`<label class="button" for="attach-pdf">${icon('upload')}Attach PDF</label><input type="file" id="attach-pdf" accept="application/pdf,.pdf" hidden>`:''}`:''}</div>${external?`<p>Found via Crossref. Check the publisher page for the full text and publication details.</p><div class="modal-actions"><button class="button primary" data-import="${esc(p.id)}">Add to library</button></div>`:`<form id="detail-form"><div class="two-fields"><div class="field"><label for="detail-status">Reading status</label><select id="detail-status"><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></div><div class="field"><label for="detail-priority">Importance</label><select id="detail-priority"><option value="high">High</option><option value="normal">Normal</option><option value="low">Low</option></select></div></div><div class="field"><label for="detail-title">Title</label><input id="detail-title" value="${esc(p.title)}" required></div><div class="field"><label for="detail-authors">Authors</label><input id="detail-authors" value="${esc(p.authors)}"></div><div class="two-fields"><div class="field"><label for="detail-year">Publication year</label><input id="detail-year" type="number" min="1400" max="2100" value="${esc(p.year)}"></div><div class="field"><label for="detail-venue">Conference / journal</label><input id="detail-venue" value="${esc(p.venue)}"></div></div>${tagField('detail-tags',p.tags.join(', '))}<div class="field"><label for="detail-notes">Reading notes</label><textarea id="detail-notes" placeholder="Key ideas, questions, and things to come back to…">${esc(p.notes)}</textarea></div><details><summary style="font-size:12px;cursor:pointer">Venue rank & impact factor</summary><p style="font-size:11px">Record a metric from a source such as CORE or Journal Citation Reports. These are venue metrics; they are not a score for this paper.</p><div class="two-fields"><div class="field"><label for="metric-type">Metric</label><select id="metric-type"><option>CORE rank</option><option>Journal impact factor</option><option>SJR quartile</option></select></div><div class="field"><label for="metric-value">Value</label><input id="metric-value" value="${esc(p.rank||'')}" placeholder="e.g. A* or 4.2"></div></div><div class="two-fields"><div class="field"><label for="metric-year">Metric year</label><input id="metric-year" type="number" min="2000" max="2100" value="${esc(p.metricYear||'')}" placeholder="2025"></div><div class="field"><label for="metric-source">Source URL</label><input id="metric-source" type="url" value="${esc(p.metricSource||'')}" placeholder="https://…"></div></div>${safeUrl(p.metricSource)?`<a href="${esc(p.metricSource)}" target="_blank" rel="noopener noreferrer" style="font-size:11px">View recorded source ↗</a>`:''}</details><div id="detail-error" class="error"></div><div class="modal-actions"><button type="button" class="button danger" data-delete="${esc(p.id)}">Remove paper</button><button class="button primary" type="submit">Save changes</button></div></form>`}`);if(!external){attachTagSuggestions('detail-tags');if(remoteMode)$('#attach-pdf').onchange=e=>attachPdf(id,e.target.files[0]);$('#detail-status').value=p.status;$('#detail-priority').value=p.importance;$('#metric-type').value=p.metricType||'CORE rank';$('#detail-form').onsubmit=async e=>{try{e.preventDefault();if(saving||uploading)return;const rank=$('#metric-value').value.trim();if(rank&&(!$('#metric-year').value||!safeUrl($('#metric-source').value))){$('#detail-error').textContent='Add a year and a valid source URL for the venue metric.';return}Object.assign(p,{title:$('#detail-title').value.trim(),authors:$('#detail-authors').value.trim(),year:Number($('#detail-year').value)||'',venue:$('#detail-venue').value.trim(),status:$('#detail-status').value,importance:$('#detail-priority').value,tags:parseTags($('#detail-tags').value),notes:$('#detail-notes').value,rank,metricType:$('#metric-type').value,metricYear:$('#metric-year').value,metricSource:$('#metric-source').value,updated:Date.now()});await save();close();render();toast('Paper updated.')}catch(err){if(confirmed&&papers.some(a=>a.id===id)){details(id);$('#detail-error').textContent=err.message}else toast(err.message)}};}}
async function readPdf(id){try{const p=papers.find(p=>p.id===id);let blob=!remoteMode&&p.pdfId?await pdfStore('get',p.pdfId):null;if(!blob&&p.drivePdfId){if(!driveToken)throw new Error('Connect Google Drive in Settings to download this PDF.');const r=await driveFetch('/files/'+encodeURIComponent(p.drivePdfId)+'?alt=media');blob=await r.blob();if(!remoteMode){p.pdfId=p.id;await pdfStore('put',p.pdfId,blob);await save()}}if(!blob)throw new Error('This PDF is not on this device. Restore from Drive or upload it again.');if(readerUrl)URL.revokeObjectURL(readerUrl);readerUrl=URL.createObjectURL(blob);modal(modalTitle(p.title)+`<div class="detail-links"><a class="button" href="${readerUrl}" target="_blank">Open in new tab ↗</a><a class="button" href="${readerUrl}" download="${esc(p.pdfName||'paper.pdf')}">Download PDF</a><button class="button primary" id="reader-mark">Mark as read</button></div><iframe class="reader" title="PDF reader" src="${readerUrl}"></iframe>`,true);$('#reader-mark').onclick=async()=>{try{const current=papers.find(a=>a.id===id);if(!current)throw new Error('This paper was removed.');current.status='read';current.updated=Date.now();await save();render();toast('Marked as read.')}catch(err){toast(err.message)}}}catch(e){toast(e.message)}}
function bibEscape(s){return String(s||'').replace(/[\\{}%&#_$]/g,c=>'\\'+c)}
function citation(p,format){const isPreprint=p.type==='posted-content'||(!p.type&&/Cryptology ePrint Archive/i.test(p.venue||''));const isConference=!isPreprint&&/proceedings|conference|symposium|EUROCRYPT/i.test(p.type||p.venue);const authors=p.authors.split(';').map(a=>a.trim()).filter(Boolean);if(format==='plain')return `${authors.join(', ')}${p.year?' ('+p.year+').':'.'} ${p.title}. ${p.venue||''}.${p.doi?' https://doi.org/'+p.doi:p.url?' '+p.url:''}`;if(format==='ris')return `TY  - ${isConference?'CPAPER':'JOUR'}\nTI  - ${p.title}\n${authors.map(a=>'AU  - '+a).join('\n')}\nPY  - ${p.year}\nJO  - ${p.venue}\nDO  - ${p.doi||''}\nUR  - ${p.url||''}\nER  -`;const name=authors[0]?.split(' ').at(-1)?.replace(/[^a-zA-Z]/g,'')||'paper';return `@${isPreprint?'misc':isConference?'inproceedings':'article'}{${name}${p.year||''}_${p.id.slice(-4)},\n  title = {${bibEscape(p.title)}},\n  author = {${authors.map(bibEscape).join(' and ')}},\n  year = {${p.year}},\n  ${isPreprint?'howpublished':isConference?'booktitle':'journal'} = {${bibEscape(p.venue)}}${p.doi?',\n  doi = {'+bibEscape(p.doi)+'}':''}${p.url?',\n  url = {'+bibEscape(p.url)+'}':''}\n}`}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function cite(id){const list=id?papers.filter(p=>p.id===id):papers;let format='bibtex';modal(modalTitle(id?'A citation, ready to go.':'Export your library.')+`<div class="field"><label for="cite-format">Citation format</label><select id="cite-format"><option value="bibtex">BibTeX</option><option value="ris">RIS</option><option value="plain">Plain text</option></select></div><p style="font-size:11px">${list.length} ${list.length===1?'paper':'papers'} · Review metadata for your preferred citation style.</p><pre class="citation-block" id="citation-output"></pre><div class="modal-actions"><button class="button" id="copy-citation">Copy citations</button><button class="button primary" id="download-citation">${icon('download')}Download</button></div>`);const content=()=>list.map(p=>citation(p,format)).join('\n\n');$('#citation-output').textContent=content();$('#cite-format').onchange=e=>{format=e.target.value;$('#citation-output').textContent=content()};$('#copy-citation').onclick=async()=>{try{await navigator.clipboard.writeText(content());toast('Citations copied.')}catch{toast('Clipboard unavailable. Use Download instead.')}};$('#download-citation').onclick=()=>download('folio-citations.'+({bibtex:'bib',ris:'ris',plain:'txt'}[format]),content())}
function pickPaper(){const list=filtered().filter(p=>p.status==='unread');if(!list.length){if(papers.some(p=>p.status==='unread'))toast('No unread papers match your current filters.');else navigate('discover');return}let candidates=list;if($('#prefer-important')?.checked!==false){const high=list.filter(p=>p.importance==='high');if(high.length)candidates=high}const chosen=$('#random-pick')?.checked?candidates[Math.floor(Math.random()*candidates.length)]:[...candidates].sort((a,b)=>a.added-b.added)[0];details(chosen.id);toast('Picked from your unread papers.')}
function renderDiscover(){const tags=[...new Set(papers.flatMap(p=>p.tags))].slice(0,4);$('#main').innerHTML=heading('Follow your curiosity.','Find papers beyond your library, guided by what interests you.',false)+`<section class="hero"><div class="hero-content"><div class="eyebrow">${icon('compass')} OPEN A NEW CHAPTER</div><h2>There’s always another idea to explore.</h2><p>Search live scholarly metadata, or use your library’s topics as a starting point.</p><button class="button" id="recommend">${icon('spark')}Recommend from my interests ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><div class="book-cover"></div><div class="book-front"><small>NEW PERSPECTIVES</small><em>Stay<br>curious.</em><div class="lines"></div></div><span class="spark">✦</span></div></section><form class="discover-search" id="discover-form"><label class="search">${icon('search')}<input id="discover-query" placeholder="Explore a topic, title, or author…" aria-label="Search scholarly papers" required></label><button class="button primary" id="discover-submit">Find papers</button></form><div class="tags">${tags.map(t=>`<button class="button" data-discover-topic="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="section-title"><h2>Beyond your library</h2><span class="subtle-link">Live metadata by Crossref</span></div><div id="discover-message" class="discover-message">${esc(discoverState||'Choose a topic to discover papers. Recommendations appear only when you ask.')}</div><div id="discover-results" class="paper-grid">${recommendations.map(p=>card(p,true)).join('')}</div>`;$('#discover-form').onsubmit=e=>{e.preventDefault();searchDiscovery($('#discover-query').value)};$('#recommend').onclick=()=>{const interests=papers.filter(p=>p.importance==='high').flatMap(p=>p.tags);const topic=[...new Set(interests)].slice(0,2).join(' ')||tags.slice(0,2).join(' ');if(!topic){toast('Add tags to your papers, or search a topic.');return}$('#discover-query').value=topic;searchDiscovery(topic)};}
let searchSequence=0;
async function searchDiscovery(topic){const seq=++searchSequence;const b=$('#discover-submit');b.disabled=true;$('#discover-message').textContent='Looking for new perspectives…';try{const data=await fetchJson('https://api.crossref.org/works?query.bibliographic='+encodeURIComponent(topic)+'&rows=40');if(seq!==searchSequence||view!=='discover')return;const existing=new Set(papers.map(p=>(p.doi||'').toLowerCase()));const titles=new Set(papers.map(p=>p.title.toLowerCase()));const seen=new Set();recommendations=data.message.items.filter(w=>['journal-article','proceedings-article','posted-content','dissertation'].includes(w.type)).map(crossrefPaper).filter(p=>!existing.has(p.doi.toLowerCase())&&!titles.has(p.title.toLowerCase())).filter(p=>{const t=p.title.toLowerCase();if(seen.has(t))return false;seen.add(t);return true}).slice(0,12).map(p=>({...p,tags:[topic.length>35?'Related research':topic]}));discoverState=`${recommendations.length} papers related to “${topic}” · Papers already in your library are excluded.`;$('#discover-message').textContent=discoverState;$('#discover-results').innerHTML=recommendations.length?recommendations.map(p=>card(p,true)).join(''):'<div class="empty">No new papers found. Try a broader topic.</div>'}catch(e){if(view==='discover'&&seq===searchSequence){$('#discover-message').textContent=e.message+' Your existing results are still shown.'}}finally{b.disabled=false}}
async function importPaper(id){const p=recommendations.find(p=>p.id===id);if(!p)return;if(papers.some(a=>a.doi&&a.doi===p.doi)){toast('Already in your library.');return}papers.unshift(enrichVenue({...p,added:Date.now(),updated:Date.now()}));recommendations=recommendations.filter(a=>a.id!==id);await save();close();render();toast('A new perspective added to your library.')}
function renderSettings(){if(remoteMode){renderRemoteSettings();return}const connected=driveToken&&Date.now()<tokenExpiry;$('#main').innerHTML=heading('Your library, your way.','Manage storage, Google Drive, and library backups.',false)+`${collectionSettings()}<section class="panel"><h2>${icon('drive')} Google Drive</h2><p>Back up your library data and uploaded PDFs to a dedicated <strong>Folio Library</strong> folder in your Drive. Connect your Google account, then choose when to back up or restore. Your library remains available on this device.</p><div class="field"><label for="google-client">Google OAuth client ID</label><input id="google-client" value="${esc(settings.clientId||'')}" placeholder="…apps.googleusercontent.com"><small>This is a public web client ID, not a client secret.</small></div><div class="setting-row"><button id="google-connect" class="button primary">${icon('drive')}${connected?'Reconnect Google Drive':'Connect Google Drive'}</button>${connected?'<button id="google-disconnect" class="button">Disconnect</button>':''}<span style="font-size:11px;color:#91a080">${connected?'Connected for this session':'Not connected'}</span></div><div class="setting-row"><button id="drive-backup" class="button" ${connected?'':'disabled'}>${icon('upload')}Back up to Drive</button><button id="drive-restore" class="button" ${connected?'':'disabled'}>${icon('download')}Restore / merge from Drive</button></div><p id="drive-progress" style="font-size:11px" role="status">${settings.lastBackup?'Last backup: '+esc(new Date(settings.lastBackup).toLocaleString()):'No Drive backup yet.'}</p><details style="margin-top:22px"><summary style="font-size:12px;cursor:pointer">First-time Google Drive setup</summary><div class="help" style="margin-top:15px"><ol><li>In <a href="https://console.cloud.google.com/apis/library/drive.googleapis.com" target="_blank" rel="noopener noreferrer">Google Cloud Console</a>, create a project and enable the Google Drive API.</li><li>Configure the OAuth consent screen. For a testing app, add your Google account as a test user.</li><li>Create an OAuth client of type <strong>Web application</strong>.</li><li>Add this exact Authorized JavaScript origin: <code>${esc(location.origin)}</code></li><li>Paste the client ID above and select Connect Google Drive. Allow access to files created by this app.</li></ol><p>Folio requests the limited <code>drive.file</code> scope. Access tokens stay in memory and expire; reconnect to continue. <a href="https://developers.google.com/identity/oauth2/web/guides/use-token-model" target="_blank" rel="noopener noreferrer">Google authorization guide ↗</a></p></div></details></section><section class="panel"><h2>Local backup & recovery</h2><p>Your papers and notes are saved in this browser; uploaded PDFs are stored in IndexedDB. Export a backup before clearing browser data. JSON exports contain citation data and notes; use Drive backup to include PDF files.</p><div class="setting-row"><button id="json-export" class="button">${icon('download')}Export library JSON</button><button id="json-import" class="button">${icon('upload')}Import library JSON</button><input type="file" id="json-file" accept="application/json,.json" hidden><button id="settings-cite" class="button">Export citations</button></div></section>${papers.some(p=>p.sample)?'<section class="panel danger-zone"><div><h2>Make it your own</h2><p>Remove the sample papers to start with your own research.</p></div><button class="button danger" id="remove-samples">Remove samples</button></section>':''}`;$('#google-connect').onclick=connectDrive;$('#drive-backup').onclick=backupDrive;$('#drive-restore').onclick=restoreDrive;if($('#google-disconnect'))$('#google-disconnect').onclick=()=>{if(window.google&&driveToken)google.accounts.oauth2.revoke(driveToken,()=>{});driveToken='';tokenExpiry=0;render();toast('Google Drive disconnected.')};$('#json-export').onclick=()=>download('folio-library.json',JSON.stringify({version:1,papers,exported:new Date().toISOString()},null,2),'application/json');$('#json-import').onclick=()=>$('#json-file').click();$('#settings-cite').onclick=()=>cite();$('#json-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Library JSON must be smaller than 10 MB.');mergeBackup(JSON.parse(await file.text()));await save();render();toast('Library backup merged.')}catch(err){toast('Import failed: '+err.message)}};}
async function connectDrive(){const clientId=$('#google-client').value.trim();if(!clientId.endsWith('.apps.googleusercontent.com')){toast('Enter a Google web OAuth client ID first.');return}settings.clientId=clientId;if(!window.google?.accounts?.oauth2){toast('Google sign-in is still loading or blocked. Try again.');return}google.accounts.oauth2.initTokenClient({client_id:clientId,scope:'https://www.googleapis.com/auth/drive.file',callback:async r=>{try{if(r.error){toast('Google authorization failed: '+r.error);return}if(!google.accounts.oauth2.hasGrantedAllScopes(r,'https://www.googleapis.com/auth/drive.file')){toast('Drive file permission was not granted.');return}await saveSettings();driveToken=r.access_token;tokenExpiry=Date.now()+Number(r.expires_in)*1000;render();toast(remoteMode?'Google Drive connected. PDFs you upload will be saved there.':'Google Drive connected. Choose Back up or Restore.');}catch(err){toast(err.message)}},error_callback:e=>toast('Google connection did not finish: '+(e.type||'popup closed'))}).requestAccessToken({prompt:'consent'})}
async function driveFetch(path,options={}){if(!driveToken||Date.now()>=tokenExpiry){driveToken='';throw new Error('Your Google session expired. Reconnect in Settings.')}const r=await fetch((path.startsWith('https://www.googleapis.com/')?path:'https://www.googleapis.com/drive/v3'+path),{...options,headers:{...options.headers,Authorization:'Bearer '+driveToken},signal:AbortSignal.timeout(90000)});if(!r.ok){if(r.status===401){driveToken='';tokenExpiry=0}const body=await r.json().catch(()=>({}));throw new Error(body.error?.message||'Drive request failed ('+r.status+').')}return r}
async function driveList(q){return (await(await driveFetch('/files?q='+encodeURIComponent(q+' and trashed = false')+'&fields=files(id,name)&pageSize=100')).json()).files}
async function driveFolder(create){const found=await driveList("name = 'Folio Library' and mimeType = 'application/vnd.google-apps.folder'");if(found.length>1)throw new Error('Multiple Folio Library folders found. Rename duplicates in Drive before continuing.');if(found.length)return found[0].id;if(!create)throw new Error('No Folio Library backup folder found in this Google account.');return (await(await driveFetch('/files?fields=id',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'Folio Library',mimeType:'application/vnd.google-apps.folder'})})).json()).id}
async function driveUpload(blob,name,folder,id){const path='https://www.googleapis.com/upload/drive/v3/files'+(id?'/'+encodeURIComponent(id):'')+'?uploadType=resumable&fields=id';const metadata=id?{name}:{name,parents:[folder]};const init=await driveFetch(path,{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json','X-Upload-Content-Type':blob.type||'application/octet-stream'},body:JSON.stringify(metadata)});const uploadUrl=init.headers.get('Location');if(!uploadUrl?.startsWith('https://www.googleapis.com/'))throw new Error('Drive did not provide a valid upload session.');return (await(await driveFetch(uploadUrl,{method:'PUT',headers:{'Content-Type':blob.type||'application/octet-stream'},body:blob})).json()).id}
async function driveOperation(action){if(busy)return;busy=true;$('#drive-backup').disabled=true;$('#drive-restore').disabled=true;try{await action()}catch(e){($('#drive-progress')||{}).textContent=e.message;toast('Drive operation failed. Your library is safe.')}finally{busy=false;if($('#drive-backup')){$('#drive-backup').disabled=!driveToken;$('#drive-restore').disabled=!driveToken}}}
async function backupDrive(){await driveOperation(async()=>{const folder=await driveFolder(true);const files=await driveList("'"+folder+"' in parents");const snapshot=structuredClone(papers);for(let i=0;i<snapshot.length;i++){const p=snapshot[i];if(!p.pdfId)continue;($('#drive-progress')||{}).textContent=`Backing up PDFs… ${i+1} / ${snapshot.length}`;const blob=await pdfStore('get',p.pdfId);if(!blob){if(!p.drivePdfId)throw new Error('PDF missing on this device: '+p.title);continue}const name=p.id+'.pdf';const existing=files.find(f=>f.name===name);p.drivePdfId=await driveUpload(blob,name,folder,existing?.id);const local=papers.find(a=>a.id===p.id);if(local)local.drivePdfId=p.drivePdfId;await save()}($('#drive-progress')||{}).textContent='Saving library metadata…';const existing=files.find(f=>f.name==='library.json');await driveUpload(new Blob([JSON.stringify({version:1,papers:snapshot,exported:new Date().toISOString()})],{type:'application/json'}),'library.json',folder,existing?.id);settings.lastBackup=Date.now();await saveSettings();($('#drive-progress')||{}).textContent='Backup complete. Library and available PDFs saved to Google Drive.';toast('Google Drive backup complete.')})}
function validateBackup(data){if(data?.version!==1||!Array.isArray(data.papers)||data.papers.length>10000)throw new Error('Not a supported Folio library backup.');return data.papers.map(p=>{if(typeof p.id!=='string'||p.id.length>100||!p.id||typeof p.title!=='string'||!p.title.trim())throw new Error('Invalid paper record.');return {id:p.id,title:p.title.slice(0,500),authors:String(p.authors||'').slice(0,5000),year:Number(p.year)||'',venue:String(p.venue||'').slice(0,1000),tags:Array.isArray(p.tags)?p.tags.filter(t=>typeof t==='string').slice(0,50):[],status:['read','unread','reading'].includes(p.status)?p.status:'unread',importance:['high','normal','low'].includes(p.importance)?p.importance:'normal',url:safeUrl(p.url),doi:getDoi(String(p.doi||'')),notes:String(p.notes||'').slice(0,100000),added:Number(p.added)||Date.now(),updated:Number(p.updated)||Number(p.added)||Date.now(),sample:p.sample===true,pdfId:typeof p.pdfId==='string'?p.pdfId:undefined,pdfName:String(p.pdfName||''),drivePdfId:typeof p.drivePdfId==='string'?p.drivePdfId:undefined,rank:String(p.rank||''),metricType:String(p.metricType||''),metricYear:String(p.metricYear||''),metricSource:safeUrl(p.metricSource),type:String(p.type||'')}})}
function mergeBackup(data){const incoming=validateBackup(data);const map=new Map(papers.map(p=>[p.id,p]));for(const p of incoming){const current=map.get(p.id);if(!current)map.set(p.id,p);else if(p.updated>current.updated)map.set(p.id,{...p,pdfId:current.pdfId||p.pdfId});else if(p.drivePdfId&&!current.drivePdfId)current.drivePdfId=p.drivePdfId}papers=[...map.values()]}
async function restoreDrive(){await driveOperation(async()=>{($('#drive-progress')||{}).textContent='Reading Drive backup…';const folder=await driveFolder(false);const files=await driveList("'"+folder+"' in parents and name = 'library.json'");if(files.length!==1)throw new Error(files.length?'Multiple library backups found. Resolve duplicates in Drive.':'No library.json backup found.');const data=await(await driveFetch('/files/'+encodeURIComponent(files[0].id)+'?alt=media')).json();validateBackup(data);mergeBackup(data);await save();($('#drive-progress')||{}).textContent='Library merged. PDFs download from Drive when you open them. Newer local edits were preserved.';toast('Drive library restored and merged.')})}
function confirmAction(title,message,action){modal(modalTitle(title)+`<p>${esc(message)}</p><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button primary" id="confirm-action">Confirm</button></div>`);$('#confirm-action').onclick=async()=>{try{if(saving||uploading)return;await action();close();render()}catch(e){toast(e.message)}}}
document.addEventListener('click',async e=>{try{if(saving||uploading)return;const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-manage-collections'))manageCollections();if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.collection)navigate('library',b.dataset.collection);if(b.hasAttribute('data-filter-tag')){collection=collection===b.dataset.filterTag?'':b.dataset.filterTag;if(view==='library')location.hash=collection?'collection='+encodeURIComponent(collection):'library';render();}if(b.hasAttribute('data-close'))close();if(b.dataset.paper)details(b.dataset.paper);if(b.dataset.external)details(b.dataset.external,true);if(b.dataset.star){const p=papers.find(p=>p.id===b.dataset.star);p.importance=p.importance==='high'?'normal':'high';p.updated=Date.now();await save();render();}if(b.dataset.import)await importPaper(b.dataset.import);if(b.dataset.cite)cite(b.dataset.cite);if(b.dataset.read)await readPdf(b.dataset.read);if(b.dataset.delete)confirmAction('Remove this paper?',remoteMode?'This removes the citation and notes from your server library. The PDF in Google Drive is kept.':'This removes the citation, notes, and local PDF from this device. Your Drive backup is kept until your next backup.',async()=>{const p=papers.find(p=>p.id===b.dataset.delete);if(!remoteMode&&p.pdfId)await pdfStore('delete',p.pdfId);papers=papers.filter(item=>item.id!==p.id);await save();toast('Paper removed.')});if(b.dataset.addTab){addMode=b.dataset.addTab;renderAdd()}if(b.dataset.layout){layout=b.dataset.layout;render()}if(b.dataset.discoverTopic){$('#discover-query').value=b.dataset.discoverTopic;searchDiscovery(b.dataset.discoverTopic)}if(['add-paper','empty-add'].includes(b.id))addPaper();if(['top-export','export-library'].includes(b.id))cite();if(b.id==='pick-paper')pickPaper();if(b.id==='drive-connect')navigate('settings');if(b.id==='remove-samples')confirmAction('Start with your own papers?','Remove the sample papers. Papers you added yourself will stay in your library.',async()=>{papers=papers.filter(p=>!p.sample);await save();toast('Sample papers removed.')});if(b.id==='add-collection'){modal(modalTitle('A new collection.')+'<form id="collection-form"><div class="field"><label for="collection-name">Collection name</label><input id="collection-name" required maxlength="60" placeholder="e.g. Post-quantum cryptography"></div><div class="modal-actions"><button class="button primary">Create collection</button></div></form>');$('#collection-form').onsubmit=async e=>{try{e.preventDefault();if(saving||uploading)return;const t=$('#collection-name').value.trim();if(!t)return;settings.collections=[...new Set([...(settings.collections||[]),t])];await saveSettings();close();navigate('library',t);toast('Collection created. Add its tag to any paper.')}catch(err){toast(err.message)}}}}catch(err){toast(err.message)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});$('#modal').addEventListener('close',()=>{if(readerUrl){URL.revokeObjectURL(readerUrl);readerUrl=''}});
hydrate();const hash=location.hash.slice(1);if(hash.startsWith('collection=')){collection=decodeURIComponent(hash.slice(11))}else if(labels[hash])view=hash;if(remoteMode)startRemote();else render();

window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);const tag=h.startsWith('collection=')?decodeURIComponent(h.slice(11)):'';const next=tag?'library':(labels[h]?h:'library');if(next!==view||tag!==collection){view=next;collection=tag;query='';statusFilter='all';priorityFilter='all';render()}});


async function remoteApi(path,options={}){
 const r=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...options.headers},signal:AbortSignal.timeout(20000)});
 const data=await r.json();
 if(!r.ok){if(r.status===401)showLogin();const err=new Error(data.error||'Server request failed.');err.status=r.status;err.library=data.library;throw err}return data;
}
function acceptRemote(data){papers=data.papers;settings=data.settings;revision=data.revision;confirmed=structuredClone(data)}
async function persistRemote(){
 if(saving)throw new Error('A save is in progress. Please wait.');
 saving=true;
 try{const data=await remoteApi('/api/library',{method:'PUT',body:JSON.stringify({papers,settings,revision})});acceptRemote(data);updateSidebar()}
 catch(err){if(err.library)acceptRemote(err.library);else if(confirmed)acceptRemote(confirmed);render();toast(err.message);throw err}
 finally{saving=false}
}
function showLogin(){
 papers=[];settings={};confirmed=null;csrf='';driveToken='';tokenExpiry=0;close();updateSidebar();
 $('#main').innerHTML=heading('Your research, securely collected.','Sign in to your personal server library.',false)+`<section class="panel"><form id="login-form"><div class="field"><label for="login-password">Library password</label><input id="login-password" type="password" autocomplete="current-password" required maxlength="1024"></div><div class="error" id="login-error" role="alert"></div><button class="button primary" id="login-submit">Sign in</button></form></section>`;
 $('#login-form').onsubmit=async e=>{e.preventDefault();const b=$('#login-submit');b.disabled=true;const password=$('#login-password').value;try{const data=await remoteApi('/api/login',{method:'POST',body:JSON.stringify({password})});csrf=data.csrf;await loadRemote();}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}};
}
async function loadRemote(){acceptRemote(await remoteApi('/api/library'));render()}
async function startRemote(){
 $('#storage-label').textContent='Saved on your server';$('.local-status').innerHTML='<i></i> Server library';$('.drive-card p').textContent='Uploaded PDFs live in your Google Drive.';
 $('#main').innerHTML=heading('Opening your library…','Connecting to your server.',false);
 try{csrf=(await remoteApi('/api/session')).csrf;await loadRemote()}catch(err){if(err.status!==401){$('#main').innerHTML=heading('Cannot reach your library.',esc(err.message),false)+`<button class="button" id="retry-server">Try again</button>`;$('#retry-server').onclick=startRemote}}
}
function renderRemoteSettings(){
 const connected=driveToken&&Date.now()<tokenExpiry;
 $('#main').innerHTML=heading('Your library, wherever you read.','Citations on your server. PDFs in your Google Drive.',false)+`${collectionSettings()}<section class="panel"><h2>${icon('drive')} Google Drive for PDFs</h2><p>Citations, notes, reading status, and importance are saved on your server. Connecting Drive is optional. When you upload a PDF, it goes directly to your <strong>Folio Library</strong> folder in Drive. The server saves its file reference. Connect the same Google account on each device to read these PDFs.</p><div class="field"><label for="google-client">Google OAuth client ID</label><input id="google-client" value="${esc(settings.clientId||'')}" placeholder="…apps.googleusercontent.com"><small>A public web client ID. No client secret is needed.</small></div><div class="setting-row"><button class="button primary" id="google-connect">${connected?'Reconnect':'Connect'} Google Drive</button>${connected?'<button class="button" id="google-disconnect">Disconnect this browser</button>':''}<span>${connected?'Connected for this session':'Not connected'}</span></div><details><summary>Google Drive setup</summary><ol><li>Create a Google Cloud project and enable the Google Drive API.</li><li>Configure OAuth consent and add your account as a test user if necessary.</li><li>Create a Web application OAuth client. Add <code>${esc(location.origin)}</code> as an Authorized JavaScript origin.</li><li>Paste the public client ID above and connect. Use the same client ID and Google account on all devices.</li></ol><p>Folio requests <code>drive.file</code>. Access tokens remain in browser memory and expire; reconnect to read or upload again. You can use citations without Drive.</p></details></section><section class="panel"><h2>Server library & recovery</h2><p>The same library loads on every signed-in device. Refresh to see edits made elsewhere. Conflicting saves are rejected and load the latest library for review. JSON exports contain citations and Drive references, not PDF files.</p><div class="setting-row"><button class="button" id="refresh-library">Reload from server</button><button class="button" id="json-export">Export library JSON</button><button class="button" id="json-import">Import library JSON</button><button class="button" id="logout">Sign out</button><input type="file" id="json-file" accept="application/json,.json" hidden></div><p>To migrate a browser library, export its JSON, import here, then attach any local PDFs to their papers. PDFs previously backed up using this OAuth client can be read from their Drive references.</p></section>`;
 $('#google-connect').onclick=connectDrive;
 if($('#google-disconnect'))$('#google-disconnect').onclick=()=>{driveToken='';tokenExpiry=0;render()};
 $('#refresh-library').onclick=async()=>{try{if(saving||uploading)return;await loadRemote();toast('Latest server library loaded.')}catch(err){toast(err.message)}};
 $('#json-export').onclick=()=>download('folio-library.json',JSON.stringify({version:1,papers,exported:new Date().toISOString()},null,2),'application/json');
 $('#json-import').onclick=()=>$('#json-file').click();
 $('#json-file').onchange=async e=>{try{if(saving||uploading)return;const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Library JSON must be smaller than 10 MB.');mergeBackup(JSON.parse(await file.text()));papers.forEach(p=>delete p.pdfId);await save();render();toast('Library imported to server.')}catch(err){toast(err.message)}};
 $('#logout').onclick=async()=>{try{if(saving||uploading)return;await remoteApi('/api/logout',{method:'POST',body:'{}'});showLogin()}catch(err){toast(err.message)}};
}

async function attachPdf(id,file){
 if(!file||saving||uploading)return;uploading=true;
 const p=papers.find(p=>p.id===id);
 try{if(!driveToken||Date.now()>=tokenExpiry)throw new Error('Connect Google Drive in Settings first.');if(file.size>50*1024*1024||await file.slice(0,5).text()!=='%PDF-')throw new Error('Choose a PDF up to 50 MB.');
 $('#attach-pdf').disabled=true;
 const drivePdfId=await driveUpload(file,p.id+'.pdf',await driveFolder(true));
 p.drivePdfId=drivePdfId;p.pdfName=file.name;p.updated=Date.now();await save();details(id);toast('PDF saved to Google Drive.')
 }catch(err){toast(err.message);if($('#attach-pdf'))$('#attach-pdf').disabled=false}finally{uploading=false}
}


function renderPhoneLibrary(){
 const unread=papers.filter(p=>p.status==='unread').length;
 const read=papers.filter(p=>p.status==='read').length;
 const tags=[...new Set([...papers.flatMap(p=>p.tags||[]),...(settings.collections||[])])];
 const title=collection||(view==='queue'?'Your next read.':view==='favorites'?'Worth keeping close.':'Your reading shelf.');
 $('#main').innerHTML=`<div class="phone-heading"><div><div class="eyebrow">A LITTLE SPACE FOR BIG IDEAS</div><h1>${esc(title)}</h1><p>${view==='queue'?'One paper. A new perspective.':view==='favorites'?'The ideas you want to come back to.':`${papers.length} collected · ${read} read`}</p></div><button class="phone-add" id="add-paper" aria-label="Add paper">${icon('plus')}</button></div>
 <section class="phone-next"><div class="phone-next-top"><span>${icon('book')} ${unread} waiting to be read</span><span aria-hidden="true">✦</span></div><h2>${unread?'Make time for one good idea.':'Ready for something new?'}</h2><button class="button primary" id="pick-paper">${unread?'Pick my next read':'Discover papers'}${icon('arrow')}</button>${view==='queue'?'<div class="queue-options"><label><input id="prefer-important" type="checkbox" checked> Important first</label><label><input id="random-pick" type="checkbox"> Random pick</label></div>':''}</section>
 <div class="phone-section"><h2>${collection?'In this collection':view==='queue'?'Unread papers':view==='favorites'?'Important papers':'Your papers'} <span id="result-count" aria-live="polite"></span></h2></div>
 <label class="search phone-search">${icon('search')}<input id="search" type="search" placeholder="Search your papers…" aria-label="Search papers" value="${esc(query)}"></label>
 <div class="phone-collections" aria-label="Collections"><button data-view="library" class="${!collection&&view==='library'?'selected':''}">All papers</button>${tags.map(t=>`<button data-collection="${esc(t)}" class="${collection===t?'selected':''}">${esc(t)}</button>`).join('')}<button type="button" data-manage-collections>Manage</button><button id="add-collection" class="phone-new-collection" aria-label="Add collection">${icon('plus')}</button></div>
 <details class="phone-filters" ${statusFilter!=='all'||priorityFilter!=='all'||sort!=='newest'?'open':''}><summary>${icon('list')}Filter & sort</summary><div class="phone-filter-fields"><label>Reading status<select id="status-filter"><option value="all">All statuses</option><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></label><label>Importance<select id="priority-filter"><option value="all">All importance</option><option value="high">High</option><option value="normal">Normal</option><option value="low">Low</option></select></label><label>Sort by<select id="sort"><option value="newest">Newest added</option><option value="oldest">Oldest added</option><option value="year">Publication year</option><option value="title">Title A–Z</option><option value="importance">Importance</option></select></label></div></details>
 <div class="paper-grid phone-papers" id="paper-results"></div>${papers.some(p=>p.sample)?'<div class="sample-note"><span>Sample library</span><button id="remove-samples">Remove samples</button></div>':''}`;
 renderPapers();
 $('#status-filter').value=statusFilter;$('#priority-filter').value=priorityFilter;$('#sort').value=sort;
 $('#search').oninput=e=>{query=e.target.value;renderPapers()};
 $('#status-filter').onchange=e=>{statusFilter=e.target.value;renderPapers()};
 $('#priority-filter').onchange=e=>{priorityFilter=e.target.value;renderPapers()};
 $('#sort').onchange=e=>{sort=e.target.value;renderPapers()};
}
phoneMedia?.addEventListener('change',()=>render());


function desktopTagFilters(){
 const tags=[...new Set([...papers.flatMap(p=>p.tags||[]),...(settings.collections||[])])].sort((a,b)=>a.localeCompare(b));
 const chip=(tag,label,count)=>`<button class="filter-tag ${collection===tag?'selected':''}" data-filter-tag="${esc(tag)}" aria-pressed="${collection===tag}"><span>${esc(label)}</span><span class="filter-tag-count">${count}</span></button>`;
 return `<section class="desktop-collections" aria-labelledby="tag-filter-heading"><div class="tag-filter-heading"><h3 id="tag-filter-heading">Collections & tags</h3><button type="button" class="button" data-manage-collections>Manage collections</button><span>${collection?`Filtering by ${esc(collection)}`:'Choose a tag to filter your papers'}</span></div><div class="filter-tag-list">${chip('','All collections',papers.length)}${tags.map(tag=>chip(tag,tag,papers.filter(p=>(p.tags||[]).includes(tag)).length)).join('')}</div>${tags.length?'':'<p class="tag-filter-empty">Add tags to a paper to organize your collections.</p>'}</section>`;
}
